308	    /**
309	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
310	     * truth for how a telephone is compared and persisted, so inputs that differ only in
311	     * formatting (spaces, dashes, brackets) are treated as the same number.
312	     *
313	     * <p>The rules are:
314	     * <ul>
315	     *   <li>spaces, dashes and brackets are stripped;</li>
316	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
317	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
318	     *       is dropped from the national digits;</li>
319	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
320	     *   <li>for a recognized country code the national number (the digits after the country
321	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
322	     *       digits and {@code '+1'} requires 10.</li>
323	     * </ul>
324	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
325	     * values are returned unchanged.
326	     *
327	     * @param telephone the raw telephone, possibly {@code null}
328	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
329	     *     valid E.164 number
330	     */
331	    public static String normalizeTelephone(String telephone) {
332	        if (telephone == null) {
333	            return null;
334	        }
335	        String trimmed = telephone.trim();
336	        boolean hasCountryCode = trimmed.startsWith("+");
337	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
338	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
339	        if (hasCountryCode) {
340	            stripped = stripped.substring(1);
341	        }
342	        if (!stripped.matches("\\d+")) {
343	            return null;
344	        }
345	        String digits;
346	        if (hasCountryCode) {
347	            digits = stripped;
348	        } else {
349	            if (stripped.startsWith("0")) {
350	                stripped = stripped.substring(1);
351	            }
352	            digits = "61" + stripped;
353	        }
354	        if (digits.length() < 8 || digits.length() > 15) {
355	            return null;
356	        }
357	        if (!hasValidNationalNumberLength(digits)) {
358	            return null;
359	        }
360	        return "+" + digits;
361	    }
362	
363	    /**
364	     * Format a stored E.164 telephone for human display: the country code, a space, then the
365	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
366	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
367	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
368	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
369	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
370	     * kept unchanged elsewhere.
371	     *
372	     * @param telephone the stored E.164 telephone, possibly {@code null}
373	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
374	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
375	     *     unchanged
376	     */
377	    public static String telephoneDisplay(String telephone) {
378	        if (telephone == null) {
379	            return null;
380	        }
381	        if (!telephone.matches("\\+\\d+")) {
382	            return telephone;
383	        }
384	        String digits = telephone.substring(1);
385	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
386	            if (digits.startsWith(countryCode)) {
387	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
388	            }
389	        }
390	        return "+" + groupDigits(digits);
391	    }
392	
393	    /**
394	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
395	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
396	     * {@code "412345678"} becomes {@code "412 345 678"}).
397	     *
398	     * @param digits the national digits
399	     * @return the space-grouped digits
400	     */
401	    private static String groupDigits(String digits) {
402	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
403	        for (int i = 0; i < digits.length(); i++) {
404	            if (i > 0 && i % 3 == 0) {
405	                grouped.append(' ');
406	            }
407	            grouped.append(digits.charAt(i));
408	        }
409	        return grouped.toString();
410	    }
411	
412	    /**
413	     * Required national-number length (the count of digits after the country code) for each
414	     * recognized country code, longest country code first so the prefix match is unambiguous.
415	     */
416	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
417	    static {
418	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
419	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
420	    }
421	
422	    /**
423	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
424	     * length its country code requires. A country code with no registered length places no
425	     * additional constraint and is accepted.
426	     *
427	     * @param digits the E.164 digits without the leading {@code '+'}
428	     * @return {@code true} if the national-number length is valid for the country code
429	     */
430	    private static boolean hasValidNationalNumberLength(String digits) {
431	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
432	            String countryCode = entry.getKey();
433	            if (digits.startsWith(countryCode)) {
434	                return digits.length() - countryCode.length() == entry.getValue();
435	            }
436	        }
437	        return true;
438	    }
