440	    /**
441	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
442	     * upper-cased abbreviation.
443	     */
444	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
445	        "ST", "STREET",
446	        "RD", "ROAD",
447	        "AVE", "AVENUE");
448	
449	    /**
450	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
451	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
452	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
453	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
454	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
455	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
456	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
457	     * value. The transform is idempotent: a normalized address normalizes to itself.
458	     *
459	     * @param address the raw address, possibly {@code null}
460	     * @return the normalized form, or {@code null} if the input was {@code null}
461	     */
462	    public static String normalizeAddress(String address) {
463	        if (address == null) {
464	            return null;
465	        }
466	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
467	        if (collapsed.isEmpty()) {
468	            return collapsed;
469	        }
470	        String[] tokens = collapsed.split(" ");
471	        StringBuilder normalized = new StringBuilder(collapsed.length());
472	        for (int i = 0; i < tokens.length; i++) {
473	            if (i > 0) {
474	                normalized.append(' ');
475	            }
476	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
477	        }
478	        return normalized.toString();
479	    }
