481	    /**
482	     * Compose an owner's canonical {@code address} from the two accepted input forms, preferring the
483	     * structured fields over the flat value. When a non-blank {@code addressLine1} is present the
484	     * result is that line, with a single space and {@code addressLine2} appended when the second line
485	     * is present; otherwise the flat {@code address} value is used. All three arguments are expected
486	     * to already be normalized (see {@link #normalizeAddress(String)}). This is the single source of
487	     * truth for how an owner's address is read, so every consumer (the stored value and the response)
488	     * sees the structured fields when present and the flat value as the backward-compatible fallback.
489	     *
490	     * @param addressLine1 the normalized first structured line, possibly {@code null} or blank
491	     * @param addressLine2 the normalized optional second structured line, possibly {@code null} or blank
492	     * @param flatAddress the normalized flat address, possibly {@code null}
493	     * @return the composed address, or the flat value / {@code null} when no structured line is present
494	     */
495	    public static String composeAddress(String addressLine1, String addressLine2, String flatAddress) {
496	        if (isPresent(addressLine1)) {
497	            if (isPresent(addressLine2)) {
498	                return addressLine1 + " " + addressLine2;
499	            }
500	            return addressLine1;
501	        }
502	        return flatAddress;
503	    }
