505	    /**
506	     * Whether an address field supplies a usable value, i.e. is non-{@code null} and not blank. This
507	     * is the shared "presence" rule behind both {@link #composeAddress(String, String, String)} and
508	     * {@link #hasAddress(String, String)}, so they agree on what counts as a supplied address field.
509	     *
510	     * @param value the address field, possibly {@code null}
511	     * @return {@code true} if the value is present and non-blank
512	     */
513	    private static boolean isPresent(String value) {
514	        return value != null && !value.isBlank();
515	    }
