517	    /**
518	     * Check whether an owner supplies a postal address in at least one accepted form: a non-blank
519	     * structured {@code addressLine1}, or a non-blank flat {@code address}. This is the single source
520	     * of truth for the address presence rule, shared by the DTO validation and any persistence path.
521	     *
522	     * @param addressLine1 the structured first line, possibly {@code null}
523	     * @param address the flat address, possibly {@code null}
524	     * @return {@code true} if either form supplies a non-blank value, {@code false} otherwise
525	     */
526	    public static boolean hasAddress(String addressLine1, String address) {
527	        return isPresent(addressLine1) || isPresent(address);
528	    }
