653	    /**
654	     * The month in which the fiscal year starts (1 July). Dates on or after this month belong to
655	     * the fiscal year named for the following calendar year.
656	     */
657	    private static final int FISCAL_YEAR_START_MONTH = 7;
658	
659	    /**
660	     * Resolve the fiscal-year number for a date, where the fiscal year starts on 1 July and is
661	     * named for the calendar year in which it ends. A date in July&ndash;December belongs to the
662	     * fiscal year of the next calendar year; a date in January&ndash;June belongs to the fiscal
663	     * year of its own calendar year.
664	     *
665	     * @param date the date to resolve, never {@code null}
666	     * @return the fiscal-year number (a four-digit calendar year)
667	     */
668	    private static int fiscalYearNumber(LocalDate date) {
669	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
670	    }
