672	    /**
673	     * Compute an owner's {@code fiscalYear}, the fiscal year of a date formatted {@code 'FY<YY>'}
674	     * where {@code YY} is the last two digits of the fiscal-year number (see
675	     * {@link #fiscalYearNumber(LocalDate)}). The fiscal year starts on 1 July, so a date of
676	     * {@code 2026-08-01} yields {@code 'FY27'} and {@code 2026-03-01} yields {@code 'FY26'}.
677	     *
678	     * @param date the date to derive the fiscal year from, possibly {@code null}
679	     * @return the fiscal year, or {@code null} if {@code date} is {@code null}
680	     */
681	    public static String fiscalYear(LocalDate date) {
682	        if (date == null) {
683	            return null;
684	        }
685	        return String.format("FY%02d", fiscalYearNumber(date) % 100);
686	    }
